<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,defineAsyncComponent} from 'vue'
import NodeConfigDrawer from './components/NodeConfigDrawer.vue'
import CrmCatalogPanel from './components/CrmCatalogPanel.vue'
import VoiceLabPanel from './components/VoiceLabPanel.vue'
import VoiceAgentPanel from './components/VoiceAgentPanel.vue'
import WorkspaceOverview from './components/WorkspaceOverview.vue'
const VoiceOperationsPanel=defineAsyncComponent(()=>import('./components/VoiceOperationsPanel.vue'))
const OperationsHealthPanel=defineAsyncComponent(()=>import('./components/OperationsHealthPanel.vue'))
const IntegrationPanel=defineAsyncComponent(()=>import('./components/IntegrationPanel.vue'))
const ConversationPanel=defineAsyncComponent(()=>import('./components/ConversationPanel.vue'))
const conversationPanel=ref(null)
const InboundVoicePanel=defineAsyncComponent(()=>import('./components/InboundVoicePanel.vue'))
const TeamPanel=defineAsyncComponent(()=>import('./components/TeamPanel.vue'))
const ContactListsPanel=defineAsyncComponent(()=>import('./components/ContactListsPanel.vue'))
import {VueFlow,Handle,Position,useVueFlow} from '@vue-flow/core'
import {Background} from '@vue-flow/background'
import {Controls} from '@vue-flow/controls'
import {MiniMap} from '@vue-flow/minimap'
import {LayoutDashboard,Phone,MessageCircle,Sparkles,Workflow,Users,Layers,Plus,ArrowLeft,ArrowRight,Search,ChevronDown,MoreHorizontal,Play,Pause,Save,X,Settings2,Zap,GitBranch,Send,Check,LogOut,BarChart3,Clock,Mail,MousePointer2,Trash2,ShieldCheck,Briefcase,ExternalLink,Link2} from 'lucide-vue-next'
import '@vue-flow/core/dist/style.css'
import '@vue-flow/core/dist/theme-default.css'
import '@vue-flow/controls/dist/style.css'
import '@vue-flow/minimap/dist/style.css'
const {screenToFlowCoordinate,addEdges,fitView,updateNodeInternals}=useVueFlow()
const catalogOverlay=ref(null),configError=ref(''),validationResult=ref(null)
const ready=ref(false),user=ref(null),page=ref('overview'),state=ref({journeys:[],audiences:[],contacts:[],catalog:[],crm_records:[]}),selected=ref(null),detail=ref({metrics:[],logs:[],subscribers:[]}),nodes=ref([]),edges=ref([]),tab=ref('journey'),search=ref(''),nodeSearch=ref(''),modal=ref(null),editing=ref(null),notice=ref(''),error=ref(''),busy=ref(false),dirty=ref(false),collapsed=ref({}),from=ref(''),to=ref('')
let noticeTimer
watch(notice,()=>{clearTimeout(noticeTimer);if(notice.value)noticeTimer=setTimeout(()=>notice.value='',5500)})
onBeforeUnmount(()=>clearTimeout(noticeTimer))
const voiceJourneys=ref([]),voiceFocus=ref(null),voiceJourneysError=ref('')
const voicePanel=ref(null),voiceSection=ref('flow'),voiceSub=ref(''),pendingNavigation=ref(null)
const agentPanel=ref(null),operationMounted=ref(false)
watch(page,value=>{if(value==='operation')operationMounted.value=true},{immediate:true})
const isAgent=computed(()=>!!user.value?.voice_workspace_id&&!['admin','supervisor'].includes(user.value?.voice_role))
const navigation=computed(()=>isAgent.value?[{key:'operation',label:'Minha operação',icon:Phone},{key:'conversations',label:'Conversas',icon:MessageCircle}]:[{key:'overview',label:'Visão geral',icon:LayoutDashboard},{key:'journeys',label:'Cadências',icon:Workflow},{key:'operation',label:'Minha operação',icon:Phone},{key:'conversations',label:'Conversas',icon:MessageCircle},{key:'queues',label:'Filas de atendimento',icon:Layers},{key:'health',label:'Saúde e limites',icon:ShieldCheck},{key:'inbound',label:'Receptivo',icon:Phone},{key:'team',label:'Equipe e acessos',icon:Users},{key:'contacts',label:'Contatos',icon:Users},{key:'audiences',label:'Segmentos',icon:Layers},{key:'crm',label:'Tarefas e negócios',icon:Briefcase},{key:'catalog',label:'Referências do CRM',icon:Link2},{key:'integrations',label:'Integrações',icon:Settings2}])
const navigationGroups=computed(()=>isAgent.value?[{label:'Atendimento',items:navigation.value}]:[{label:'Operação',keys:['overview','journeys','operation','conversations']},{label:'Público',keys:['contacts','audiences']},{label:'Gestão',keys:['queues','team','inbound','health']},{label:'Integrações',keys:['integrations','catalog','crm']}].map(g=>({...g,items:navigation.value.filter(i=>g.keys.includes(i.key))})))
const cadenceSections=[['all','Todas as cadências'],['channels','Canais'],['reports','Relatórios'],['tests','Testes']]
const inCadences=computed(()=>!!selected.value||['journeys','voice'].includes(page.value))
const activeCadenceSection=computed(()=>page.value==='voice'&&!['flow','create'].includes(voiceSection.value)?voiceSection.value:'all')
function route(path){if(location.hash!=='#'+path)history.pushState(null,'','#'+path)}
function requestNavigation(fn){if(page.value==='conversations'&&conversationPanel.value){conversationPanel.value.requestLeave(fn);return}if(page.value==='operation'&&agentPanel.value){agentPanel.value.requestLeave(fn);return}if(dirty.value){pendingNavigation.value=fn;modal.value='leave';return}if(page.value==='voice'&&voicePanel.value){voicePanel.value.requestLeave(fn);return}fn()}
function discardNavigation(){dirty.value=false;selected.value=null;modal.value=null;const fn=pendingNavigation.value;pendingNavigation.value=null;if(fn)fn();else refresh()}
function showCadences(section='all',sub=''){selected.value=null;voiceFocus.value=null;voiceSection.value=section==='new-voice'?'create':section;voiceSub.value=sub;page.value=section==='all'?'journeys':'voice';route('/cadences'+(section==='all'?'':'/'+section)+(sub?'/'+sub:''))}
function cadenceNavigate(section,sub=''){requestNavigation(()=>showCadences(section,sub))}
function createVoice(){modal.value=null;cadenceNavigate('new-voice')}

async function refreshVoiceJourneys(){if(isAgent.value){voiceJourneys.value=[];return}try{voiceJourneys.value=await api('/api/voice/journeys');voiceJourneysError.value=''}catch{voiceJourneysError.value='Não foi possível atualizar as jornadas de voz. A lista pode estar incompleta.'}}
function openVoiceJourney(id){voiceFocus.value=Number(id);selected.value=null;voiceSection.value='flow';voiceSub.value='';page.value='voice';route('/cadences/voice/'+id)}
function syncHash(){if(isAgent.value){page.value=location.hash==='#/conversations'?'conversations':'operation';selected.value=null;route('/'+page.value);return}const path=location.hash.slice(1)||'/overview';let match=path.match(/^\/(?:voice\/journey|cadences\/voice)\/(\d+)$/);if(match){openVoiceJourney(match[1]);return}match=path.match(/^\/cadences\/automation\/(\d+)$/);if(match){if(user.value)open({id:Number(match[1])});return}match=path.match(/^\/cadences\/(queues|channels|reports|tests|new-voice)(?:\/([a-z]+))?$/);if(match){showCadences(match[1],match[2]||'');return}if(['/journeys','/voice','/cadences'].includes(path)){showCadences();return}const key=path.slice(1);if(['overview','queues','health','conversations','inbound','team','operation','contacts','audiences','crm','catalog','integrations'].includes(key)){page.value=key;selected.value=null;voiceFocus.value=null}}
function navigate(key){if(isAgent.value&&!['operation','conversations'].includes(key))key='operation';requestNavigation(()=>{if(['journeys','voice'].includes(key)){showCadences();return}page.value=key;selected.value=null;voiceFocus.value=null;route('/'+key)})}
function hashNavigation(){requestNavigation(syncHash)}
onMounted(()=>{syncHash();window.addEventListener('hashchange',hashNavigation)})
onBeforeUnmount(()=>window.removeEventListener('hashchange',hashNavigation))
const login=ref({email:'',password:''})
const localDate=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const form=ref({}),config=ref({}),enrollContact=ref('')
const labels={draft:'Rascunho',active:'Ativa',paused:'Pausada',completed:'Concluída',waiting:'Em espera',failed:'Com erro',pending:'Na fila',cancelled:'Cancelada'}
const groups=[{key:'trigger',label:'Gatilhos',desc:'Como tudo começa',icon:Zap},{key:'process',label:'Processos',desc:'Decisões e caminhos',icon:GitBranch},{key:'action',label:'Ações',desc:'Conecte e engaje',icon:Send}]
const fieldNames={field:'Campo do contato',operator:'Operador',value:'Valor',branches:'Regras dos caminhos (JSON)',event:'Evento esperado',minutes:'Tempo em minutos',percentage:'Percentual do caminho A',template:'Modelo / template',subject:'Assunto',language:'Idioma',parameters:'Parâmetros (JSON)',buttons:'Botões de resposta (JSON)',audience_id:'Lista',tag:'Tag',score:'Pontuação',stage:'Estágio',recipient:'Destinatário interno',subscribed:'Assinatura ativa',url:'URL HTTPS',method:'Método HTTP',payload:'Payload (JSON)',journey_id:'Jornada de destino',title:'Título',assignee:'Responsável',amount:'Valor'}
const normalizeSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
function journeyTimestamp(value){if(!value)return 0;return Date.parse(/^\d{4}-\d\d-\d\d \d\d:/.test(value)?value.replace(' ','T')+'Z':value)||0}
function journeyDate(value){const time=journeyTimestamp(value);return time?new Date(time).toLocaleDateString('pt-BR'):'—'}
function automationChannels(j){const keys=new Set((j.graph?.nodes||[]).map(n=>n.data?.key));return Object.entries({send_whatsapp:'WhatsApp',send_email:'E-mail',send_sms:'SMS'}).filter(([key])=>keys.has(key)).map(([,label])=>label)}
const allJourneys=computed(()=>[
 ...state.value.journeys.map(j=>({key:'automation-'+j.id,id:j.id,kind:'automation',title:j.title,description:j.description||'Jornada de automação',status:j.status,channels:automationChannels(j),audience:j.audiences.map(a=>a.name).join(', ')||'Sem lista vinculada',count:j.subscribers_count,countLabel:'entradas',updated_at:j.updated_at})),
 ...voiceJourneys.value.map(j=>({key:'voice-'+j.id,id:j.id,kind:'voice',title:j.name,description:'Até '+j.settings.max_attempts+' tentativas · '+(j.retry_minutes?.no_answer??j.settings.retry_minutes)+' min de intervalo',status:j.status,channels:j.settings.whatsapp_enabled?['Voz','WhatsApp']:['Voz'],audience:j.list?.name||'Contatos da campanha',count:j.contact_count,countLabel:'contatos vinculados',updated_at:j.updated_at}))
].sort((a,b)=>journeyTimestamp(b.updated_at)-journeyTimestamp(a.updated_at)||a.title.localeCompare(b.title,'pt-BR')||a.key.localeCompare(b.key)))
const activeCount=computed(()=>allJourneys.value.filter(j=>['active','testing'].includes(j.status)).length)
const filtered=computed(()=>{const term=normalizeSearch(search.value.trim());return allJourneys.value.filter(j=>normalizeSearch([j.title,j.description,j.audience,...j.channels].join(' ')).includes(term))})
function openListedJourney(j){if(j.kind==='voice')openVoiceJourney(j.id);else open(j)}
const meta=key=>state.value.catalog.find(c=>c.key===key)||{}
const ports=data=>[...(meta(data.key).ports||['success']),...(data.key==='send_whatsapp'&&Array.isArray(data.settings?.buttons)?data.settings.buttons:[])]
const metric=(id,status)=>Number(detail.value.metrics.find(m=>m.node_uuid===id&&m.status===status)?.total||0)
const totalMetric=status=>detail.value.metrics.filter(m=>m.status===status).reduce((a,m)=>a+Number(m.total),0)
async function api(url,method='GET',body){const r=await fetch(url,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível concluir.');return d}
async function run(fn){error.value='';notice.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){state.value=await api('/api/bootstrap');user.value=state.value.user;await refreshVoiceJourneys()}
onMounted(async()=>{try{await refresh();syncHash()}catch{}finally{ready.value=true}})
async function signIn(){await run(async()=>{await api('/login','POST',login.value);location.reload()})}
function start(kind){form.value=kind==='journey'?{title:'',description:'',audience_ids:[],start_date:localDate(),end_date:'',is_indefinite:true}:kind==='contact'?{name:'',email:'',phone:'',subscribed:false,audience_ids:[]}:{name:''};modal.value=kind}
async function create(){await run(async()=>{const kind=modal.value;const body={...form.value};if(kind==='journey'){body.start_date=new Date(body.start_date).toISOString();body.end_date=body.is_indefinite?null:new Date(body.end_date).toISOString()}const data=await api('/api/'+({journey:'journeys',contact:'contacts',audience:'audiences'}[kind]),'POST',body);modal.value=null;await refresh();if(kind==='journey')await open(data);else notice.value='Cadastro salvo.'})}
async function open(j){await run(async()=>{const d=await api('/api/journeys/'+j.id);selected.value=d.journey;page.value='journeys';route('/cadences/automation/'+j.id);detail.value=d;nodes.value=(d.journey.graph?.nodes||[]).map(n=>({...n,type:'journey'}));edges.value=d.journey.graph?.edges||[];dirty.value=false;tab.value='journey';setTimeout(()=>fitView({padding:.25}),100)})}
async function report(){await run(async()=>{detail.value=await api('/api/journeys/'+selected.value.id+'?'+new URLSearchParams({...(from.value?{from:from.value}:{}),...(to.value?{to:to.value}:{})}))})}
function graph(){return {nodes:nodes.value.map(n=>({id:n.id,type:'journey',position:n.position,data:{key:n.data.key,settings:n.data.settings||{}}})),edges:edges.value.map(e=>({id:e.id,source:e.source,target:e.target,sourceHandle:e.sourceHandle||'success',targetHandle:e.targetHandle||null}))}}
async function saveGraph(){selected.value=await api('/api/journeys/'+selected.value.id+'/graph','PUT',{revision:selected.value.revision,graph:graph()});dirty.value=false;notice.value='Alterações salvas.'}
async function publish(){await run(async()=>{await saveGraph();selected.value=await api('/api/journeys/'+selected.value.id+'/publish','POST');await refresh();notice.value='Jornada publicada. Novas entradas usam a versão '+selected.value.published_version+'.'})}
async function changeStatus(action){await run(async()=>{selected.value=await api('/api/journeys/'+selected.value.id+'/'+action,'POST');await refresh()})}
function addNode(key,position){const n={id:crypto.randomUUID(),type:'journey',position:position||{x:220,y:80+nodes.value.length*260},data:{key,settings:{_config_version:2,...Object.fromEntries((meta(key).schema?.fields||[]).filter(f=>'default'in f).map(f=>[f.key,f.default]))}}};nodes.value.push(n);dirty.value=true;configure(n)}
function drag(event,key){event.dataTransfer.setData('application/zyrex-node',key);event.dataTransfer.effectAllowed='move'}
function drop(event){event.preventDefault();const key=event.dataTransfer.getData('application/zyrex-node');if(key)addNode(key,screenToFlowCoordinate({x:event.clientX,y:event.clientY}))}
function connect(e){addEdges([{...e,id:crypto.randomUUID(),type:'smoothstep'}]);dirty.value=true}
function configure(n){if(!n)return;editing.value=n.id;configError.value=''}
function nodeClick({node,event}){if(event?.target?.closest('.vue-flow__handle,button'))return;configure(node)}
const editingNode=computed(()=>nodes.value.find(n=>n.id===editing.value))
function updateSettings(settings){const node=editingNode.value;if(!node)return;const nextPorts=ports({key:node.data.key,settings});const stranded=edges.value.filter(e=>e.source===node.id&&!nextPorts.includes(e.sourceHandle||'success'));if(stranded.length){configError.value='Remova primeiro as conexões das saídas que deseja excluir ou renomear.';return;}node.data={...node.data,settings};dirty.value=true;configError.value='';validationResult.value=null;setTimeout(()=>updateNodeInternals([node.id]),0)}
async function saveConfig(){configError.value='';busy.value=true;try{const result=await api('/api/node-config/validate','POST',{key:editingNode.value.data.key,settings:editingNode.value.data.settings||{}});await saveGraph();notice.value=result.activation_pending.length?'Configuração salva. Referências prontas para a integração com o CRM.':'Configuração salva.';editing.value=null}catch(e){configError.value=e.message}finally{busy.value=false}}
async function validateFlow(){await run(async()=>{validationResult.value=await api('/api/graph/validate','POST',{graph:graph()});notice.value=validationResult.value.activation_pending.length?'Fluxo válido para preparação. A ativação aguarda a conexão do CRM.':'Configuração do fluxo validada.'})}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
function deleteNode(){const id=editing.value;nodes.value=nodes.value.filter(n=>n.id!==id);edges.value=edges.value.filter(e=>e.source!==id&&e.target!==id);editing.value=null;dirty.value=true}
function summary(data){const s=data.settings||{};return s._labels?.segment_id||s._labels?.campaign_id||s._labels?.template||s.segment_id||s.campaign_id||s.form_id||s.template||s.tag||s.title||(s.minutes?s.minutes+' minutos':null)||(s.field?s.field+' '+(s.operator||'')+' '+(s.value||''):null)||'Clique para configurar'}
function back(){requestNavigation(()=>{showCadences();refresh()})}
async function enroll(){await run(async()=>{await api('/api/journeys/'+selected.value.id+'/enroll','POST',{contact_id:Number(enrollContact.value),event_key:crypto.randomUUID()});await report();notice.value='Contato encaminhado à fila.'})}
</script>
<template>
 <div v-if="!ready" class="loading">Preparando seu espaço…</div>
 <main v-else-if="!user" class="login-page">
  <section class="login-story"><div class="brand"><img class="zyrex-mark" :src="'/brand/zyrex-mark.svg'" alt=""> Zyrex<span class="brand-light">/ marketing</span></div><div><span class="eyebrow light">CONEXÕES QUE CONTINUAM</span><h1>Cada contato.<br>Uma nova<br><em>possibilidade.</em></h1><p>Crie jornadas que aproximam sua marca<br>das pessoas, no momento certo.</p></div><span class="login-foot">Marketing Automation · Zyrex</span></section>
  <section class="login-form"><span class="pill"><ShieldCheck :size="14"/> Seu espaço de trabalho</span><h2>Bem-vindo de volta.</h2><p>Entre para acompanhar suas jornadas.</p><form @submit.prevent="signIn"><label>E-mail<input v-model="login.email" type="email" required autocomplete="username" placeholder="voce@empresa.com.br"></label><label>Senha<input v-model="login.password" type="password" required autocomplete="current-password" placeholder="Sua senha"></label><div v-if="error" class="error">{{error}}</div><button class="primary" :disabled="busy">Entrar no workspace <ArrowRight :size="17"/></button></form><small>Acesso restrito à equipe autorizada.</small></section>
 </main>
 <div v-else class="workspace">
  <aside class="main-nav"><a class="brand" href="#/overview" @click.prevent="navigate(isAgent?'operation':'overview')"><img class="zyrex-mark" :src="'/brand/zyrex-mark.svg'" alt=""><span class="zyrex-wordmark">Zyrex<span class="brand-dot">.</span></span></a><div class="workspace-label">MARKETING AUTOMATION</div><div class="workspace-switch"><span class="workspace-avatar">Z</span><div>Zyrex Workspace<small>Seu espaço de conexão</small></div><ChevronDown :size="14"/></div><nav class="nav-groups" aria-label="Navegação principal"><section v-for="group in navigationGroups" :key="group.label" class="nav-group"><span class="nav-caption">{{group.label}}</span><button v-for="item in group.items" :key="item.key" :class="['nav-item',{active:item.key==='journeys'?inCadences:page===item.key}]" @click="navigate(item.key)" :title="item.label" :aria-label="item.label"><component :is="item.icon" :size="18"/><span class="nav-label">{{item.label}}</span><span v-if="item.key==='journeys'" class="nav-count">{{allJourneys.length}}</span></button></section></nav><div class="nav-bottom"><div class="tip"><Zap :size="19"/><strong>Menos tarefas.<br>Mais relações.</strong><p>Uma boa jornada começa com o próximo passo.</p></div><div class="profile"><span class="avatar">{{user.name[0]}}</span><div>{{user.name}}<small>{{isAgent?'Atendente':user.voice_role==='supervisor'?'Supervisor':'Administrador'}}</small></div><button title="Sair" @click="requestNavigation(()=>run(async()=>{await agentPanel?.shutdown();await api('/api/logout','POST');location.reload()}))"><LogOut :size="17"/></button></div></div></aside>
  <div class="main-area" :class="{'compact-cadence':page==='voice'&&['flow','create'].includes(voiceSection)}">
   <header class="topbar"><div class="breadcrumb">Workspace <span>/</span> {{selected?'Cadências':({overview:'Visão geral',queues:'Filas de atendimento',team:'Equipe e acessos',inbound:'Receptivo',conversations:'Conversas',health:'Saúde e limites',operation:'Minha operação',journeys:'Cadências',contacts:'Contatos',audiences:'Segmentos',crm:'Tarefas e negócios',catalog:'Referências do CRM',integrations:'Integrações',voice:'Cadências'}[page])}} <template v-if="selected"><span>/</span><b>{{selected.title}}</b></template></div><div class="topbar-tools"><div id="agent-toolbar"/><span class="environment"><span></span> Workspace conectado</span></div></header>
   <div v-if="error||notice" :class="['toast',error?'error':'success']" :role="error?'alert':'status'">{{error||notice}}<button @click="error='';notice='' "><X :size="16"/></button></div>
   <nav v-if="inCadences" class="cadence-nav" aria-label="Áreas de cadências"><button v-for="[key,label] in cadenceSections" :key="key" :class="{active:activeCadenceSection===key}" :aria-current="activeCadenceSection===key?'page':undefined" @click="cadenceNavigate(key)">{{label}}</button></nav>
   <template v-if="selected">
    <header class="journey-header"><button class="icon-btn" title="Voltar" @click="back"><ArrowLeft :size="20"/></button><div class="journey-heading"><div class="title-row"><h2>{{selected.title}}</h2><span :class="['status',selected.status]">{{labels[selected.status]}}</span></div><p>{{dirty?'Alterações não salvas':'Todas as alterações salvas'}} <span v-if="selected.published_version"> · Versão publicada {{selected.published_version}}</span></p></div><button :disabled="busy" class="secondary" @click="run(saveGraph)"><Save :size="16"/> Salvar</button><button v-if="selected.status==='active'" class="secondary" @click="changeStatus('pause')"><Pause :size="15"/> Pausar</button><button v-if="selected.status==='paused'&&selected.published_version" class="secondary" @click="changeStatus('resume')"><Play :size="15"/> Retomar</button><button :disabled="busy" class="secondary" @click="validateFlow"><Check :size="15"/> Validar fluxo</button><button :disabled="busy" class="primary" @click="publish"><Play :size="15"/> Publicar cadência</button></header>
    <div class="tabs"><button v-for="t in [{id:'journey',label:'FLUXO',icon:Workflow},{id:'reports',label:'RELATÓRIOS',icon:BarChart3},{id:'contacts',label:'CONTATOS',icon:Users}]" :class="{selected:tab===t.id}" @click="tab=t.id;if(t.id!=='journey')report()"><component :is="t.icon" :size="15"/>{{t.label}}</button><span class="tabs-note"><Clock :size="14"/>{{selected.is_indefinite?'Duração contínua':'Vigência definida'}}</span></div>
    <div v-if="tab==='journey'" class="editor">
     <aside class="components"><div class="components-heading"><h3>Construa sua cadência</h3><p>Arraste os componentes para o fluxo.</p></div><div class="search"><Search :size="15"/><input v-model="nodeSearch" placeholder="Pesquisar componentes"></div><section v-for="g in groups" :key="g.key" class="component-group"><button class="category" @click="collapsed[g.key]=!collapsed[g.key]"><span :class="['category-icon',g.key]"><component :is="g.icon" :size="14"/></span>{{g.label.toUpperCase()}}<ChevronDown :size="14"/></button><div v-if="!collapsed[g.key]"><button v-for="c in state.catalog.filter(c=>c.type===g.key&&c.label.toLowerCase().includes(nodeSearch.toLowerCase()))" :key="c.key" class="component" draggable="true" @dragstart="drag($event,c.key)" @click="addNode(c.key)"><span :class="['node-icon',g.key]"><component :is="g.icon" :size="14"/></span>{{c.label}}<Plus :size="12"/></button></div></section></aside>
     <div class="canvas" @drop="drop" @dragover.prevent>
      <VueFlow v-model:nodes="nodes" v-model:edges="edges" :default-viewport="{zoom:.85,x:50,y:30}" :min-zoom=".25" :max-zoom="1.8" :default-edge-options="{type:'smoothstep',style:{stroke:'#a89cbc',strokeWidth:2}}" @connect="connect" @node-click="nodeClick" @node-double-click="({node})=>configure(node)" @node-drag-stop="dirty=true" @edges-change="changes=>{if(changes.some(c=>c.type==='remove'))dirty=true}">
       <Background pattern-color="#d7d3df" :gap="22" :size="1"/><Controls/><MiniMap :node-color="n=>({trigger:'#f8c869',process:'#b3a0e8',action:'#91ccb9'}[meta(n.data.key).type])"/>
       <template #node-journey="{id,data}"><div :class="['journey-node',meta(data.key).type]"><Handle v-if="meta(data.key).type!=='trigger'" type="target" :position="Position.Top"/><div class="node-top"><span :class="['node-icon',meta(data.key).type]"><Zap v-if="meta(data.key).type==='trigger'" :size="17"/><GitBranch v-else-if="meta(data.key).type==='process'" :size="17"/><Send v-else :size="17"/></span><span>{{meta(data.key).type==='trigger'?'GATILHO':meta(data.key).type==='process'?'PROCESSO':'AÇÃO'}}</span><button class="nodrag" @click.stop="configure(nodes.find(n=>n.id===id))" title="Configurar nó"><Settings2 :size="15"/></button></div><strong>{{meta(data.key).label}}</strong><p>{{summary(data)}}</p><div class="node-metrics"><span><Users :size="12"/>{{metric(id,'success')+metric(id,'failed')}}</span><span><Check :size="12"/>{{metric(id,'success')}}</span><span><X :size="12"/>{{metric(id,'failed')}}</span></div><div class="node-ports"><span v-for="(port,i) in ports(data)" :key="port">{{({success:'Próximo',yes:'Sim',no:'Não',timeout:'Tempo esgotado',sent:'Enviado',delivered:'Entregue',read:'Lido',failed:'Falhou'}[port])||port}}<Handle type="source" :id="port" :position="Position.Bottom" :style="{left:((i+.5)/ports(data).length*100)+'%'}"/></span></div></div></template>
      </VueFlow><div v-if="nodes.length===0" class="canvas-empty"><span><MousePointer2 :size="28"/></span><h3>Toda conexão tem um começo.</h3><p>Arraste um gatilho para cá e dê<br>o primeiro passo na sua jornada.</p><button @click="addNode('open_trigger')">Começar com gatilho por API <ArrowRight :size="15"/></button></div><div class="canvas-caption">{{nodes.length}} nós <span>·</span> {{edges.length}} conexões</div>
     </div>
     <NodeConfigDrawer v-if="editingNode" :key="editingNode.id" :node="editingNode" :meta="meta(editingNode.data.key)" :audiences="state.audiences" :journeys="state.journeys" :journey-id="selected.id" :busy="busy" :error="configError" @update="updateSettings" @save="saveConfig" @close="editing=null" @delete="deleteNode" @catalog="catalogOverlay=$event"/>

    </div>
    <section v-else-if="tab==='reports'" class="content"><div class="section-heading"><div><span class="eyebrow">RESULTADOS DA JORNADA</span><h1>Cada passo, em números.</h1></div><div class="period"><input type="date" v-model="from" aria-label="Início do período"><span>até</span><input type="date" v-model="to" aria-label="Fim do período"><button class="secondary" @click="report">Filtrar</button></div></div><div class="stats"><article><span>Execuções concluídas</span><strong>{{totalMetric('success')}}</strong><small>Ações processadas com sucesso</small></article><article><span>Execuções com erro</span><strong>{{totalMetric('failed')}}</strong><small>Consulte os detalhes abaixo</small></article><article><span>Contatos em espera</span><strong>{{detail.subscribers.filter(s=>s.status==='waiting').length}}</strong><small>Estado atual · até 500 entradas</small></article></div><div class="table-card"><h3>Histórico de execução</h3><table><thead><tr><th>Componente</th><th>Contato</th><th>Resultado</th><th>Detalhes</th><th>Quando</th></tr></thead><tbody><tr v-for="l in detail.logs"><td>{{meta(nodes.find(n=>n.id===l.node_uuid)?.data.key).label||l.node_uuid}}</td><td>#{{l.contact_id}}</td><td><span :class="['status',l.status==='success'?'active':'failed']">{{l.status==='success'?'Sucesso':'Erro'}}</span></td><td>{{l.response?.error||l.response?.port||'—'}}</td><td>{{new Date(l.executed_at).toLocaleString('pt-BR')}}</td></tr></tbody></table><div v-if="!detail.logs.length" class="empty-small">Os resultados aparecerão quando os contatos percorrerem a jornada.</div></div></section>
    <section v-else class="content"><div class="section-heading"><div><span class="eyebrow">PESSOAS EM MOVIMENTO</span><h1>Contatos na jornada</h1></div><button class="secondary" @click="report">Atualizar</button></div><div class="enrollment"><div><strong>Entrada manual por API</strong><p>Requer gatilho por API, jornada ativa e contato no público selecionado.</p></div><select v-model="enrollContact"><option value="">Selecione um contato</option><option v-for="c in state.contacts" :value="c.id">{{c.name}}</option></select><button class="primary" :disabled="!enrollContact||busy" @click="enroll">Adicionar à jornada</button></div><div class="table-card"><table><thead><tr><th>Contato</th><th>E-mail</th><th>Status</th><th>Versão</th><th>Entrada</th></tr></thead><tbody><tr v-for="s in detail.subscribers"><td>{{s.contact.name}}</td><td>{{s.contact.email||'—'}}</td><td><span :class="['status',s.status]">{{labels[s.status]||s.status}}</span></td><td>v{{s.version}}</td><td>{{new Date(s.entered_at).toLocaleString('pt-BR')}}</td></tr></tbody></table><div v-if="!detail.subscribers.length" class="empty-small">Nenhum contato entrou nesta jornada ainda.</div></div></section>
   </template>
   <section v-else-if="page==='overview'" class="content"><WorkspaceOverview :journeys="allJourneys" :name="user.name" @navigate="navigate" @cadences="cadenceNavigate"/></section>
   <section v-else-if="page==='journeys'" class="content"><div class="section-heading journeys-hero"><div><span class="eyebrow">AUTOMAÇÃO COM PROPÓSITO</span><h1>Suas cadências</h1><p>Voz, mensagens e automação. Cada contato, com o próximo passo definido.</p></div><button class="primary" @click="modal='cadenceType'"><Plus :size="18"/> Nova cadência</button></div><div class="stats"><article><span><Workflow :size="17"/> Total de cadências</span><strong>{{allJourneys.length}}<small>cadências criadas</small></strong><div class="stat-line purple"></div></article><article><span><Zap :size="17"/> Ativas / habilitadas</span><strong>{{activeCount}}<small>conectando pessoas</small></strong><div class="stat-line green"></div></article><article><span><Users :size="17"/> Contatos cadastrados</span><strong>{{state.contacts.length}}<small>na sua base · até 500</small></strong><div class="stat-line amber"></div></article></div><p v-if="voiceJourneysError" class="error" role="alert">{{voiceJourneysError}} <button class="secondary" @click="refreshVoiceJourneys">Tentar novamente</button></p><div class="table-card journeys-table"><div class="table-toolbar"><h3>Todas as cadências <span>{{allJourneys.length}}</span></h3><div class="search"><Search :size="16"/><input aria-label="Buscar cadências" v-model="search" placeholder="Buscar cadência ou canal…"></div></div><div v-if="filtered.length" class="journey-table-scroll"><table><thead><tr><th>NOME DA CADÊNCIA</th><th>CANAIS</th><th>STATUS</th><th>PÚBLICO</th><th>CONTATOS / ENTRADAS</th><th>ATUALIZADA EM</th><th><span class="journey-sr-only">Abrir</span></th></tr></thead><tbody><tr v-for="j in filtered" :key="j.key" :data-journey-key="j.key" @click="openListedJourney(j)" class="clickable"><td><div class="journey-name"><span class="journey-symbol"><Phone v-if="j.kind==='voice'" :size="20"/><Workflow v-else :size="20"/></span><div><button class="journey-title-button" @click.stop="openListedJourney(j)">{{j.title}}</button><small>{{j.description}}</small></div></div></td><td><div class="journey-channels"><span v-for="channel in j.channels.length?j.channels:['Automação']" :key="channel">{{channel}}</span></div></td><td><span :class="['status',j.status==='testing'?'active':j.status]">{{j.status==='testing'?'Habilitada':labels[j.status]||j.status}}</span></td><td>{{j.audience}}</td><td>{{j.count}}<small class="journey-count-label">{{j.countLabel}}</small></td><td>{{journeyDate(j.updated_at)}}</td><td><button class="journey-open-button" :aria-label="'Abrir cadência '+j.title" @click.stop="openListedJourney(j)"><ArrowRight :size="17"/></button></td></tr></tbody></table></div><div v-else class="empty-state"><div class="empty-art"><Workflow :size="38"/><span><Zap :size="19"/></span></div><h2>{{search?'Nenhuma cadência encontrada':'Sua primeira cadência começa aqui.'}}</h2><p>{{search?'Busque pelo nome, público ou canal da jornada.':'Escolha seu público, desenhe os próximos passos e crie conexões no momento certo.'}}</p><button v-if="search" class="secondary" @click="search=''">Limpar busca</button><button v-else class="primary" @click="modal='cadenceType'"><Plus :size="16"/> Criar minha primeira cadência</button></div></div><div class="bottom-note"><ShieldCheck :size="15"/> Seu workspace possui armazenamento e processamento exclusivos.</div></section>
   <section v-else-if="page==='audiences'" class="content"><ContactListsPanel @changed="refresh"/></section>
   <section v-else-if="page==='contacts'" class="content"><div class="section-heading"><div><span class="eyebrow">CONHEÇA SEU PÚBLICO</span><h1>{{page==='contacts'?'Contatos':'Segmentos'}}</h1><p>Organize as pessoas que fazem parte das suas jornadas.</p></div><button class="primary" @click="start(page==='contacts'?'contact':'audience')"><Plus :size="17"/>{{page==='contacts'?'Novo contato':'Nova lista'}}</button></div><div class="table-card"><table><thead><tr><th>Nome</th><th>{{page==='contacts'?'E-mail':'Contatos'}}</th><th>{{page==='contacts'?'Listas':'Tipo'}}</th><th v-if="page==='contacts'">Assinatura</th></tr></thead><tbody><tr v-for="c in page==='contacts'?state.contacts:state.audiences"><td><strong>{{c.name}}</strong></td><td>{{page==='contacts'?c.email||'—':c.contacts_count}}</td><td>{{page==='contacts'?c.audiences.map(a=>a.name).join(', ')||'—':'Lista'}}</td><td v-if="page==='contacts'"><span :class="['status',c.subscribed?'active':'paused']">{{c.subscribed?'Ativa':'Sem opt-in'}}</span></td></tr></tbody></table><div v-if="!(page==='contacts'?state.contacts:state.audiences).length" class="empty-state"><Users :size="36"/><h2>Vamos conhecer seu público?</h2><p>Comece criando {{page==='contacts'?'um contato com consentimento de envio':'uma lista para organizar seus contatos'}}.</p></div></div></section>
   <section v-else-if="page==='crm'" class="content"><div class="section-heading"><div><span class="eyebrow">PRÓXIMOS PASSOS</span><h1>Tarefas e negócios</h1><p>Registros criados pelas ações das suas jornadas.</p></div></div><div class="table-card"><table><thead><tr><th>Título</th><th>Tipo</th><th>Contato</th><th>Criado em</th></tr></thead><tbody><tr v-for="r in state.crm_records"><td>{{r.title}}</td><td>{{r.type==='task'?'Tarefa':'Negócio'}}</td><td>#{{r.contact_id}}</td><td>{{new Date(r.created_at).toLocaleString('pt-BR')}}</td></tr></tbody></table><div v-if="!state.crm_records.length" class="empty-small">Nenhum registro criado pelas jornadas.</div></div></section>
   <template v-else-if="page==='operation'"/>
   <section v-else-if="page==='voice'" class="content"><VoiceLabPanel ref="voicePanel" :key="voiceSection+':'+voiceFocus+':'+voiceSub" :section="voiceSection" :initial-sub="voiceSub" :focus-id="voiceFocus" @section="cadenceNavigate" @back="cadenceNavigate('all')" @catalog="navigate('catalog')" @lists="navigate('audiences')" @journey="openVoiceJourney" @changed="refreshVoiceJourneys"/></section>
   <section v-else-if="page==='conversations'" class="content"><ConversationPanel ref="conversationPanel"/></section>
   <section v-else-if="page==='queues'" class="content"><VoiceOperationsPanel initial-tab="live" :allowed-tabs="['live']"/></section>
   <section v-else-if="page==='health'" class="content"><OperationsHealthPanel/></section>
   <section v-else-if="page==='inbound'" class="content"><InboundVoicePanel supervisor/></section>
   <section v-else-if="page==='team'" class="content"><TeamPanel/></section>
   <section v-else-if="page==='catalog'" class="content"><CrmCatalogPanel/></section>
   <section v-else class="content"><IntegrationPanel/></section>
   <section v-if="isAgent||operationMounted" v-show="page==='operation'" class="content"><VoiceAgentPanel ref="agentPanel" toolbar-target="#agent-toolbar" :visible="page==='operation'" @open-operation="navigate('operation')"/></section>
  </div>
  <div v-if="catalogOverlay" class="modal-backdrop catalog-overlay"><CrmCatalogPanel :initial-kind="catalogOverlay" modal @close="catalogOverlay=null"/></div>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><form class="modal" @submit.prevent="create"><div class="modal-title"><div><span class="eyebrow">{{modal==='journey'?'UM NOVO COMEÇO':'SEU WORKSPACE'}}</span><h2>{{({cadenceType:'Que cadência você quer criar?',journey:'Nova cadência de automação',contact:'Novo contato',audience:'Nova lista',leave:'Alterações não salvas'}[modal])}}</h2></div><button type="button" @click="modal=null"><X :size="21"/></button></div><template v-if="modal==='cadenceType'"><p>Escolha o fluxo inicial. As duas opções ficam reunidas na mesma lista.</p><div class="cadence-choices"><button type="button" class="secondary" aria-label="Automação" @click="start('journey')"><Workflow :size="22"/><strong>Automação</strong><span>Gatilhos, condições e ações no editor visual.</span></button><button type="button" class="secondary" aria-label="Voz e WhatsApp" @click="createVoice"><Phone :size="22"/><strong>Voz e WhatsApp</strong><span>Tentativas de ligação e mensagem após não atendimento.</span></button></div></template><template v-else-if="modal==='leave'"><p>Salve o fluxo antes de voltar ou descarte as alterações desta sessão.</p><div class="modal-actions"><button type="button" class="secondary" @click="modal=null">Continuar editando</button><button type="button" class="primary" @click="discardNavigation">Descartar e voltar</button></div></template><template v-else><p class="modal-intro">{{modal==='journey'?'Defina o público e o período. Depois, dê forma à sua ideia no editor visual.':'Preencha os dados para começar.'}}</p><label>{{modal==='journey'?'Nome da cadência':'Nome'}}<input v-if="modal==='journey'" v-model="form.title" required maxlength="160" placeholder="Ex.: Boas-vindas para novos contatos"><input v-else v-model="form.name" required maxlength="160" placeholder="Digite o nome"></label><label v-if="modal==='journey'">Descrição <span class="optional">opcional</span><textarea v-model="form.description" placeholder="Qual é o objetivo desta jornada?" rows="2"/></label><template v-if="modal==='contact'"><div class="form-row"><label>E-mail<input type="email" v-model="form.email"></label><label>WhatsApp / telefone<input v-model="form.phone" placeholder="+55…"></label></div><label class="check-label"><input type="checkbox" v-model="form.subscribed">Confirmo que o contato autorizou comunicações de marketing.</label></template><template v-if="modal!=='audience'"><label>Público / listas de contatos</label><div class="audience-picker"><label v-for="a in state.audiences" class="check-label"><input type="checkbox" :value="a.id" v-model="form.audience_ids">{{a.name}}</label><p v-if="!state.audiences.length">Crie uma lista na seção “Segmentos” antes de criar a jornada.</p></div></template><template v-if="modal==='journey'"><div class="form-row"><label>Data e hora de início<input type="datetime-local" v-model="form.start_date" required></label><label>Data e hora de término<input type="datetime-local" v-model="form.end_date" :disabled="form.is_indefinite" :required="!form.is_indefinite"></label></div><label class="check-label"><input type="checkbox" v-model="form.is_indefinite">Duração indefinida / contínua</label></template><div v-if="error" class="error">{{error}}</div><div class="modal-actions"><button type="button" class="secondary" @click="modal=null">Cancelar</button><button class="primary" :disabled="busy||(modal==='journey'&&!form.audience_ids.length)">{{modal==='journey'?'Criar e abrir editor':'Salvar cadastro'}}<ArrowRight :size="16"/></button></div></template></form></div>
 </div>
</template>

